        "mode=" + encodeEnumString("grounded_box_2d"),
        "parameters.box_width_m=" + encodeF64(p.box_width_m),
        "parameters.left_electrode.center_x_m=" + encodeF64(le.center_x_m),
        "parameters.left_electrode.center_y_m=" + encodeF64(le.center_y_m),
        "parameters.left_electrode.radius_m=" + encodeF64(le.radius_m),
        "parameters.left_electrode.voltage_v=" + encodeF64(le.voltage_v),
        "parameters.n=" + encodeInt(p.n),
        "parameters.right_electrode.center_x_m=" + encodeF64(re.center_x_m),
        "parameters.right_electrode.center_y_m=" + encodeF64(re.center_y_m),
        "parameters.right_electrode.radius_m=" + encodeF64(re.radius_m),
        "parameters.right_electrode.voltage_v=" + encodeF64(re.voltage_v),
        "probe_xy_m=[" + encodeF64(probe[0]) + "," + encodeF64(probe[1]) + "]",
        "study_n_list=[" + encodedLevels + "]"
